    print("  first 40 SMs by start time:", list(first[:40]))
    print("  start spread ns: first148 %d, all %d" % (t[order[147]]-t0 if n>147 else -1, t.max()-t0))
    # first 148 CTAs distinct SMs?
    print("  distinct SMs among first 148 starts:", len(set(first.tolist())))

import torch, b200probe, numpy as np
src = r'''
extern "C" __global__ void lat(const unsigned* buf, const long long* off, int n, unsigned* lat, int target, int* flag, unsigned* sink){
  unsigned s; asm volatile("mov.u32 %0, %%smid;":"=r"(s));
  if (s != (unsigned)target || threadIdx.x) return;
  if (atomicCAS(flag, 0, 1) != 0) return;
  unsigned acc = 0;
  for (int i = 0; i < n; i++) {
    const unsigned* p = buf + (off[i] >> 2) + (acc & 0);  // dependent address
    unsigned long long t0, t1; unsigned v, w;
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t0) :: "memory");
    asm volatile("ld.global.cg.u32 %0, [%1];" : "=r"(v) : "l"(p) : "memory");
    asm volatile("add.u32 %0, %1, 1;" : "=r"(w) : "r"(v) : "memory");
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t1) :: "memory");
    acc += w;
    lat[i] = (unsigned)(t1 - t0);
  }
  sink[0] = acc;
}
'''
k = b200probe.cuda_kernel(src, "lat")
buf = torch.zeros(64<<20 >> 2, dtype=torch.int32, device='cuda')
sink = torch.zeros(4, dtype=torch.int32, device='cuda')
N = 4096
def run(sm, offs):
    flag = torch.zeros(1, dtype=torch.int32, device='cuda')
    out = torch.zeros(N, dtype=torch.int32, device='cuda')
    k((592,), (32,), buf, offs, N, out, sm, flag, sink); torch.cuda.synchronize()
    assert flag.item()==1, "no CTA on sm %d"%sm
    return out.cpu().numpy().astype(np.int64)
def summ(a):
    q = np.percentile(a, [5,25,50,75,95])
    return "p5/25/50/75/95=" + "/".join(str(int(v)) for v in q)
def split(a, offs_np, tag):
    # 2-means threshold
    lo, hi = np.percentile(a,10), np.percentile(a,90)
    for _ in range(20):
        th = (lo+hi)/2; lo = a[a<=th].mean(); hi = a[a>th].mean() if (a>th).any() else hi
    m = a > th
    frac = m.mean()
    bits = []
    for b in range(7, 26):
        bit = (offs_np >> b) & 1
        c = abs(np.corrcoef(bit, m)[0,1]) if m.std()>0 and bit.std()>0 else 0
        bits.append((b, round(float(c),2)))
    bits.sort(key=lambda z: -z[1])
    print(f"   {tag}: lo~{lo:.0f} hi~{hi:.0f} far-frac {frac:.2f} top bits {bits[:4]}")
    return m
for stride in [128, 4096, 16384]:
    offs_np = (np.arange(N, dtype=np.int64) * stride) % (64<<20)
    offs = torch.tensor(offs_np, device='cuda')
    print(f"stride {stride}")
    masks = {}
    for sm in [0, 37, 74, 111, 147]:
        b200probe.flush_l2()
        cold = run(sm, offs)
        warm = run(sm, offs)
        print(f" SM{sm:3d} cold {summ(cold)} | warm {summ(warm)}")
        masks[sm] = split(warm, offs_np, "warm")
        split(cold, offs_np, "cold")
    sms = list(masks)
    print("  warm far-mask agreement vs SM0:", [round(float((masks[s]==masks[0]).mean()),2) for s in sms])

