# read-only stream: each CTA (128 thr, 4KB chunk per iteration via 32B/thread) grabs chunks from list of its die via atomic counter
src = r'''
extern "C" __global__ void __launch_bounds__(128) rd(const float* __restrict__ x, const int* l0, int n0, const int* l1, int n1,
     const int* smdie, int* ctr, int mode, float* out){
  unsigned s; asm volatile("mov.u32 %0, %%smid;":"=r"(s));
  int d = smdie[s];
  if (mode == 2) d ^= 1;          // remote
  __shared__ int idx;
  float acc = 0.f;
  while (true) {
    if (threadIdx.x == 0) {
      int dd = d; int i;
      if (mode == 0) { i = atomicAdd(&ctr[2], 1); idx = (i < n0 + n1) ? i : -1; }    // all chunks in order
      else { i = atomicAdd(&ctr[dd], 1); int nn = dd ? n1 : n0; idx = (i < nn) ? (dd ? l1[i] : l0[i]) : -1; }
    }
    __syncthreads();
    int c = idx;
    __syncthreads();
    if (c < 0) break;
    const float* p = x + (long long)c * 1024 + threadIdx.x * 8;
    float v[8];
    asm volatile("ld.global.nc.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(v[0]),"=f"(v[1]),"=f"(v[2]),"=f"(v[3]),"=f"(v[4]),"=f"(v[5]),"=f"(v[6]),"=f"(v[7]) : "l"(p));
    #pragma unroll
    for (int j=0;j<8;j++) acc += v[j];
  }
  if (acc == 12345.f) out[0] = acc;
}
